contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        // Baseline observable before the deciding call.
        address ownerBefore = c.smartfix_owner();
        uint256 balanceBefore = address(c).balance;

        // The only deciding call; must be a top-level statement.
        // msg.sender for this call is this test contract, via low-level-like direct call.
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call reverts iff the caller is not the recorded smartfix_owner.
        // If it does not revert, the contract is killed and its balance moves to the owner.
        assert(reverted == (ownerBefore != msg.sender || caller != ownerBefore));
    }

    receive() external payable {}
}

