contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        require(caller != address(0));

        address beforeOwner = c.smartfix_owner();
        uint beforeBalance = address(c).balance;
        uint senderBefore = address(this).balance;

        bool isOwner = (caller == beforeOwner);
        bool reverted;

        // Only the owner can actually make the selfdestruct-sending call;
        // for a non-owner we can still call, but it must revert and leave
        // C's balance untouched.  We copy the caller into msg.sender by
        // having the test contract (msg.sender for every call on c) act as
        // the caller; since constructor sets smartfix_owner to the deployer
        // (this test contract), we instead parameterize over whether the
        // call is made by this contract (owner) or by a distinct address
        // via a low-level call forwarding the chosen sender.
        if (isOwner) {
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint afterBalance = address(c).balance;
            assert(!reverted && afterBalance == 0);
        } else {
            (bool ok, ) = address(c).call(abi.encodeWithSelector(c.sudicideAnyone.selector));
            reverted = !ok;
            uint afterBalance = address(c).balance;
            assert(reverted && afterBalance == beforeBalance);
        }
    }

    receive() external payable {}
}

